import json, random, statistics
from collections import Counter, defaultdict
from vs import corpus, ivtff

PAIRS=[('y','q'),('n','q'),('y','o'),('n','o'),('y','ch'),('n','ch'),('y','d'),('n','d')]
DRAWS=199

def get_rows(trans):
    pages,_=corpus.split_pages('practice',trans)
    rows=[]
    for p in pages:
        first=True
        for line in p.lines:
            if not line.words: continue
            pfl=line.unit=='P' and (line.para_start or first)
            if line.unit=='P':
                n=len(line.words)
                for i,(a,b) in enumerate(zip(line.words,line.words[1:])):
                    if ivtff.uncertain(a) or ivtff.uncertain(b): continue
                    ga,gb=ivtff.segment(a),ivtff.segment(b)
                    if ga and gb:
                        rows.append((ga[-1],gb[0],p.id,p.section or '?',int(pfl),n,i))
                first=line.para_end
    return rows

def measure(rows,scheme):
    pools=defaultdict(list)
    for i,r in enumerate(rows):
        key={'global':(), 'section_position':(r[3],r[4],r[5],r[6]), 'page_position':(r[2],r[4],r[5],r[6])}[scheme]
        pools[key].append(i)
    rng=random.Random(39086)
    observed=Counter((r[0],r[1]) for r in rows)
    sim=[]
    for _ in range(DRAWS):
        c=Counter()
        for indices in pools.values():
            right=[rows[i][1] for i in indices]
            rng.shuffle(right)
            c.update((rows[i][0],b) for i,b in zip(indices,right))
        sim.append([c[pair] for pair in PAIRS])
    expected=[statistics.mean(row[j] for row in sim) for j in range(len(PAIRS))]
    # Centred discrepancy: exploratory, not a preregistered hypothesis test.
    score=lambda vals:sum(abs(x-e)/(max(e,1)**.5) for x,e in zip(vals,expected))
    obs=[observed[p] for p in PAIRS]
    ss=score(obs)
    return {'boundaries':len(rows),'groups':len(pools),'fraction_in_groups_size_at_least_2':round(sum(len(g) for g in pools.values() if len(g)>1)/len(rows),4),
       'pairs':{'.'.join(p):{'observed':obs[j],'shuffle_mean':round(expected[j],2),'difference':round(obs[j]-expected[j],2),'shuffle_range':[min(s[j] for s in sim),max(s[j] for s in sim)]} for j,p in enumerate(PAIRS)},
       'aggregate_abs_standardized_residual':round(ss,3),'empirical_upper_tail':round((1+sum(score(s)>=ss for s in sim))/(DRAWS+1),4)}

def synthetic():
    # Both tables have identical layout; correlated pairs should survive a layout-conditioned shuffle.
    rng=random.Random(7); null=[]; assoc=[]
    for j in range(2400):
        a=rng.choice(['y','n']); b=rng.choice(['q','o'])
        base=(str(j//120),'H',j%2,8,j%7)
        null.append((a,b,*base)); assoc.append((a,'q' if a=='y' else 'o',*base))
    return {name:measure(rows,'page_position')['empirical_upper_tail'] for name,rows in [('independent',null),('linked',assoc)]}

if __name__=='__main__':
    result={'spec':{'pairs':PAIRS,'draws':DRAWS,'seed':39086},'synthetic':synthetic(),'transliterations':{}}
    for t in ('zl','it'):
        rows=get_rows(t)
        result['transliterations'][t]={s:measure(rows,s) for s in ('global','section_position','page_position')}
    print(json.dumps(result,indent=2))
